using System;
using System.IO;
using System.Linq;
using PowerPointIntelligence.AddIn;
using Office=Microsoft.Office.Core;
using PowerPoint=Microsoft.Office.Interop.PowerPoint;
internal static class IndicatorOfficeTests {
 static int count;static void Check(bool v,string name){if(!v)throw new Exception("FAIL indicator Office: "+name);count++;Console.WriteLine("PASS indicator Office: "+name);}
 static PowerPoint.Shape Current(PowerPoint.Application app){return app.ActiveWindow.Selection.ShapeRange[1];}
 internal static void Run(PowerPoint.Application app,string outputDirectory){if(app==null)throw new ArgumentNullException("app");count=0;Directory.CreateDirectory(outputDirectory);string file=Path.Combine(Path.GetFullPath(outputDirectory),"indicator-native-"+Guid.NewGuid().ToString("N")+".pptx");PowerPoint.Presentation deck=null;Console.WriteLine("INDICATOR Office="+app.Version+" process="+(Environment.Is64BitProcess?"x64":"x86"));try{
 deck=app.Presentations.Add(Office.MsoTriState.msoTrue);deck.PageSetup.SlideWidth=960;deck.PageSetup.SlideHeight=540;deck.Windows[1].ViewType=PowerPoint.PpViewType.ppViewNormal;var slide=deck.Slides.Add(1,PowerPoint.PpSlideLayout.ppLayoutBlank);slide.Select();var unrelated=slide.Shapes.AddShape(Office.MsoAutoShapeType.msoShapeRectangle,10,10,20,20);int unrelatedId=unrelated.Id;
 var ball=IndicatorElements.Insert(app,"harvey");Check(ball.Type==Office.MsoShapeType.msoGroup&&ball.GroupItems.Count>=2&&IndicatorElements.Read(ball).Filled==1,"native vector Harvey group inserted");ball.Select();IndicatorElements.CycleSelected(app);ball=Current(app);Check(IndicatorElements.Read(ball).Filled==2,"double click core increment");IndicatorElements.Step(app,-99);ball=Current(app);Check(IndicatorElements.Read(ball).Filled==0,"decrement clamps");var spec=IndicatorElements.Read(ball);spec.Segments=100;spec.Filled=13;spec.SizePt=48;spec.FilledColor=0x123456;spec.UnfilledColor=0xAABBCC;spec.BackgroundColor=0xEEDDCC;spec.OutlineColor=0x334455;IndicatorElements.Configure(app,spec);ball=Current(app);Check(Math.Abs(ball.Width-48)<.1&&IndicatorElements.Read(ball).Segments==100&&ball.GroupItems[1].Fill.ForeColor.RGB==spec.BackgroundColor,"size and four color preset persisted");IndicatorElements.SetShortcut(app,6);ball=Current(app);Check(IndicatorElements.Read(ball).Filled==75,"eight fraction numeric shortcut");ball.Left=120;ball.Top=140;ball.Width=64;ball.Height=56;float left=ball.Left,top=ball.Top,width=ball.Width,height=ball.Height;IndicatorElements.ConvertSelected(app,"checkbox");var box=Current(app);Check(IndicatorElements.Read(box).Kind=="checkbox"&&Math.Abs(box.Left-left)<.1&&Math.Abs(box.Top-top)<.1&&Math.Abs(box.Width-width)<.1&&Math.Abs(box.Height-height)<.1,"conversion preserves bounds");IndicatorElements.SetShortcut(app,1);box=Current(app);Check(IndicatorElements.Read(box).CheckState==1&&box.GroupItems.Count==4,"check state uses two editable vector strokes");IndicatorElements.CycleSelected(app);box=Current(app);Check(IndicatorElements.Read(box).CheckState==2,"checkbox cycles to cross");box.GroupItems[3].Line.ForeColor.RGB=0x00FF00;Check(box.GroupItems[3].Line.ForeColor.RGB==0x00FF00,"native child accepts direct formatting edit");
 var duplicate=box.Duplicate()[1];duplicate.Left=300;duplicate.Select();Check(IndicatorElements.Read(duplicate).CheckState==2,"native duplicate retains CustomerData");IndicatorElements.SetShortcut(app,0);duplicate=Current(app);Check(IndicatorElements.Read(box).CheckState==2&&IndicatorElements.Read(duplicate).CheckState==0,"duplicate metadata updates independently");int boxId=box.Id,copyId=duplicate.Id;deck.SaveAs(file,PowerPoint.PpSaveAsFileType.ppSaveAsOpenXMLPresentation,Office.MsoTriState.msoFalse);deck.Close();deck=null;deck=app.Presentations.Open(file,Office.MsoTriState.msoFalse,Office.MsoTriState.msoFalse,Office.MsoTriState.msoTrue);deck.Windows[1].ViewType=PowerPoint.PpViewType.ppViewNormal;slide=deck.Slides[1];slide.Select();box=slide.Shapes.Cast<PowerPoint.Shape>().Single(x=>x.Id==boxId);duplicate=slide.Shapes.Cast<PowerPoint.Shape>().Single(x=>x.Id==copyId);Check(IndicatorElements.Read(box).CheckState==2&&IndicatorElements.Read(duplicate).CheckState==0,"typed versioned states survive save reopen");Check(box.GroupItems[3].Line.ForeColor.RGB==0x00FF00,"direct child edit survives save reopen");box.GroupItems[3].Line.Weight=4;Check(Math.Abs(box.GroupItems[3].Line.Weight-4)<.1,"native child remains editable after reopen");
 var invalid=duplicate.Duplicate()[1];var part=invalid.CustomerData.Add();part.LoadXML(IndicatorCodec.Encode(new IndicatorSpec{Kind="checkbox"}));int before=slide.Shapes.Count;invalid.Select();bool rejected=false;try{IndicatorElements.Step(app,1);}catch(InvalidDataException){rejected=true;}Check(rejected&&slide.Shapes.Count==before&&slide.Shapes.Cast<PowerPoint.Shape>().Any(x=>x.Id==unrelatedId),"ambiguous metadata rejected without removing any object");invalid.Delete();box.Select();IndicatorElements.SetValueSelected(app,0);Check(IndicatorElements.Read(Current(app)).CheckState==0,"linked value adapter sets checkbox");deck.Save();Console.WriteLine("INDICATOR "+count+" native assertions passed. Evidence deck: "+file);
 }finally{if(deck!=null){deck.Saved=Office.MsoTriState.msoTrue;deck.Close();}}}
}
